-- L01:deDE, L02:esES, L03:esMX, L04:frFR, L05:itIT, L06:ptBR, L07:ruRU, L08:koKR, L09:zhCN, L10:zhTW

-- Create locale structure (missing phrases fall back to the English key)
local void, Leatrix_Plus = ...
local function localeFunc(L, key) return key end
local L = setmetatable({}, {__index = localeFunc})
Leatrix_Plus.L = L

-- Use the game locale unless one is chosen in the settings dropdown (1 is Automatic)
local GameLocale = GetLocale()
local localeList = {"enUS", "deDE", "esES", "esMX", "frFR", "itIT", "ptBR", "ruRU", "koKR", "zhCN", "zhTW"}
local choice = LeaPlusDB and LeaPlusDB["AddonLanguage"]
if type(choice) == "number" and localeList[choice - 1] then
	GameLocale = localeList[choice - 1]
end

