	L["Invalid battle pet team parameter."] = "无效的宠物对战队伍参数。"
	L["Invalid console variable."] = "无效控制台缓存。"
	L["Invalid map ID."] = "无效的地图ID。"
	L["Invalid parameter."] = "无效参数"
